"""Load SSB data (generated by the pinned BenchBox generator) into DuckDB as the pipeline's sources.

Adds what the SSB schema lacks and a pipeline needs: lo_rowid (single-column key), lo_loaded_ts (when the row
landed: order date plus 0-2 days, deterministic) so source partitions (load date) differ from business dates.
"""

from __future__ import annotations

from pathlib import Path

import duckdb

BENCHBOX_PIN = "0.4.1"


def generate(sf: float, out_dir: Path) -> Path:
    out_dir = Path(out_dir)
    if not (out_dir / "lineorder.tbl").exists():
        from benchbox import SSB  # pip install benchbox==0.4.1

        SSB(scale_factor=sf, output_dir=str(out_dir)).generate_data()
    return out_dir


def _read(con, f, cols):
    spec = ", ".join(f"'{c}': '{t}'" for c, t in cols)
    return f"read_csv('{f}', delim='|', header=false, columns={{{spec}}})"


def load_sources(con: duckdb.DuckDBPyConnection, d: Path) -> None:
    d = Path(d)
    T = {
        "customer": [
            ("c_custkey", "INT"),
            ("c_name", "VARCHAR"),
            ("c_address", "VARCHAR"),
            ("c_city", "VARCHAR"),
            ("c_nation", "VARCHAR"),
            ("c_region", "VARCHAR"),
            ("c_phone", "VARCHAR"),
            ("c_mktsegment", "VARCHAR"),
        ],
        "supplier": [
            ("s_suppkey", "INT"),
            ("s_name", "VARCHAR"),
            ("s_address", "VARCHAR"),
            ("s_city", "VARCHAR"),
            ("s_nation", "VARCHAR"),
            ("s_region", "VARCHAR"),
            ("s_phone", "VARCHAR"),
        ],
        "part": [
            ("p_partkey", "INT"),
            ("p_name", "VARCHAR"),
            ("p_mfgr", "VARCHAR"),
            ("p_category", "VARCHAR"),
            ("p_brand1", "VARCHAR"),
            ("p_color", "VARCHAR"),
            ("p_type", "VARCHAR"),
            ("p_size", "INT"),
            ("p_container", "VARCHAR"),
        ],
    }
    for n, cols in T.items():
        con.execute(f"CREATE TABLE {n} AS SELECT * FROM {_read(con, d / (n + '.tbl'), cols)}")
    dcols = [
        ("d_datekey", "INT"),
        ("d_date", "VARCHAR"),
        ("d_dayofweek", "VARCHAR"),
        ("d_month", "VARCHAR"),
        ("d_year", "INT"),
        ("d_yearmonthnum", "INT"),
        ("d_yearmonth", "VARCHAR"),
        ("d_daynuminweek", "INT"),
        ("d_daynuminmonth", "INT"),
        ("d_daynuminyear", "INT"),
        ("d_monthnuminyear", "INT"),
        ("d_weeknuminyear", "INT"),
        ("d_sellingseason", "VARCHAR"),
        ("d_lastdayinweekfl", "INT"),
        ("d_lastdayinmonthfl", "INT"),
        ("d_holidayfl", "INT"),
        ("d_weekdayfl", "INT"),
    ]
    con.execute(
        f"CREATE TABLE dates AS SELECT * REPLACE (CAST(strptime(d_date, '%Y-%m-%d') AS DATE) AS d_date) "
        f"FROM {_read(con, d / 'date.tbl', dcols)}"
    )
    lcols = [
        ("lo_orderkey", "INT"),
        ("lo_linenumber", "INT"),
        ("lo_custkey", "INT"),
        ("lo_partkey", "INT"),
        ("lo_suppkey", "INT"),
        ("lo_orderdate", "INT"),
        ("lo_orderpriority", "VARCHAR"),
        ("lo_shippriority", "INT"),
        ("lo_quantity", "INT"),
        ("lo_extendedprice", "INT"),
        ("lo_ordtotalprice", "INT"),
        ("lo_discount", "INT"),
        ("lo_revenue", "INT"),
        ("lo_supplycost", "INT"),
        ("lo_tax", "INT"),
        ("lo_commitdate", "INT"),
        ("lo_shipmode", "VARCHAR"),
    ]
    con.execute(f"""CREATE TABLE lineorder AS
        SELECT CAST(lo_orderkey AS BIGINT) * 10 + lo_linenumber AS lo_rowid, lo_orderkey, lo_linenumber, lo_custkey, lo_partkey, lo_suppkey,
               CAST(strptime(CAST(lo_orderdate AS VARCHAR), '%Y%m%d') AS DATE) AS lo_orderdate,
               CAST(strptime(CAST(lo_orderdate AS VARCHAR), '%Y%m%d') AS TIMESTAMP)
                   + INTERVAL ((lo_orderkey + lo_linenumber) % 3) DAY + INTERVAL ((lo_orderkey * 7) % 24) HOUR AS lo_loaded_ts,
               lo_quantity, lo_extendedprice, lo_discount, lo_revenue, lo_supplycost
        FROM {_read(con, d / "lineorder.tbl", lcols)}""")
